```go
func computeOps(a, b []string) []Op {
    n, m := len(a), len(b)
    max := n + m
    offset := max
    v := make([]int, 2*max+1)
    var trace [][]int
    for d := 0; d <= max; d++ {
        snapshot := make([]int, len(v))
        copy(snapshot, v)
        trace = append(trace, snapshot)
        for k := -d; k <= d; k += 2 {
            var x int
            if k == -d || (k != d && v[offset+k-1] < v[offset+k+1]) {
                x = v[offset+k+1]
            } else {
                x = v[offset+k-1] + 1
            }
            y := x - k
            for x < n && y < m && a[x] == b[y] {
                x++
                y++
            }
            v[offset+k] = x
            if x >= n && y >= m {
                return backtrack(trace, a, b, offset, d)
            }
        }
    }
    return nil
}
```

