func backtrack(trace [][]int, a, b []string, offset, d int) []Op {
    x, y := len(a), len(b)
    ops := make([]Op, 0, x+y)
    for ; d >= 0; d-- {
        v := trace[d]
        k := x - y
        var prevK int
        if k == -d || (k != d && v[offset+k-1] < v[offset+k+1]) {
            prevK = k + 1
        } else {
            prevK = k - 1
        }
        prevX := v[offset+prevK]
        prevY := prevX - prevK
        for x > prevX && y > prevY {
            ops = append(ops, Op{Equal, a[x-1]})
            x--
            y--
        }
        if d == 0 {
            break
        }
        if x == prevX {
            // insertion: b[prevY] inserted
            ops = append(ops, Op{Insert, b[prevY]})
        } else {
            ops = append(ops, Op{Delete, a[prevX]})
        }
        x, y = prevX, prevY
    }
    // reverse
    for i, j := 0, len(ops)-1; i < j; i, j = i+1, j-1 {
        ops[i], ops[j] = ops[j], ops[i]
    }
    return ops
}
```

