package diff

import (
	"fmt"
	"strings"
)

// OpKind describes whether a line is unchanged, deleted from the old text, or
// inserted into the new text.
type OpKind int

const (
	// Equal marks a line present in both texts.
	Equal OpKind = iota
	// Delete marks a line present only in the old text.
	Delete
	// Insert marks a line present only in the new text.
	Insert
)

// Op is a single line-level edit operation.
type Op struct {
	Kind OpKind
	Text string
}

// Config controls how a unified diff is formatted.
type Config struct {
	// FromName and ToName label the old and new texts in the ---/+++ header.
	// Empty names default to "a" and "b".
	FromName string
	ToName   string
	// Context is the number of unchanged lines shown around each change.
	// Negative values are treated as zero.
	Context int
}

// Unified returns a unified diff between a and b using default labels ("a",
// "b") and three lines of context. It returns an empty string when a and b are
// identical.
func Unified(a, b string) string {
	return Config{}.Unified(a, b)
}

// UnifiedNamed is like Unified but labels the old and new texts with the given
// names.
func UnifiedNamed(fromName, toName, a, b string) string {
	return Config{FromName: fromName, ToName: toName}.Unified(a, b)
}

// Unified renders a unified diff between a and b. The result is empty when the
// inputs are identical.
func (c Config) Unified(a, b string) string {
	oldLines := splitLines(a)
	newLines := splitLines(b)

	ops := computeOps(oldLines, newLines)
	lines := numberLines(ops)
	hunks := groupHunks(lines, max(c.Context, 0))
	if len(hunks) == 0 {
		return ""
	}

	fromName := c.FromName
	if fromName == "" {
		fromName = "a"
	}
	toName := c.ToName
	if toName == "" {
		toName = "b"
	}

	var sb strings.Builder
	fmt.Fprintf(&sb, "--- %s\n", fromName)
	fmt.Fprintf(&sb, "+++ %s\n", toName)
	for _, h := range hunks {
		writeHunk(&sb, lines, h)
	}
	return sb.String()
}

// unifiedLine is a formatted diff line carrying the source line numbers it
// corresponds to. For an inserted line oldNo is the old line the text would be
// inserted before (similarly for deleted lines and newNo).
type unifiedLine struct {
	tag     byte // ' ', '-', or '+'
	text    string
	oldNo   int
	newNo   int
	hasOld  bool
	hasNew  bool
}

func numberLines(ops []Op) []unifiedLine {
	lines := make([]unifiedLine, 0, len(ops))
	oldNo, newNo := 1, 1
	for _, op := range ops {
		switch op.Kind {
		case Equal:
			lines = append(lines, unifiedLine{
				tag: ' ', text: op.Text, oldNo: oldNo, newNo: newNo, hasOld: true, hasNew: true,
			})
			oldNo++
			newNo++
		case Delete:
			lines = append(lines, unifiedLine{
				tag: '-', text: op.Text, oldNo: oldNo, newNo: newNo, hasOld: true,
			})
			oldNo++
		case Insert:
			lines = append(lines, unifiedLine{
				tag: '+', text: op.Text, oldNo: oldNo, newNo: newNo, hasNew: true,
			})
			newNo++
		}
	}
	return lines
}

type hunk struct {
	start int // inclusive index into the numbered lines
	end   int // inclusive index into the numbered lines
}

// groupHunks collapses changed lines into hunks padded by context unchanged
// lines, merging hunks whose context would overlap.
func groupHunks(lines []unifiedLine, context int) []hunk {
	var changes []int
	for i, l := range lines {
		if l.tag != ' ' {
			changes = append(changes, i)
		}
	}
	if len(changes) == 0 {
		return nil
	}

	var hunks []hunk
	lo, hi := changes[0], changes[0]
	flush := func() {
		start := max(lo-context, 0)
		end := min(hi+context, len(lines)-1)
		hunks = append(hunks, hunk{start: start, end: end})
	}
	for _, c := range changes[1:] {
		if c-hi-1 <= 2*context {
			hi = c
			continue
		}
		flush()
		lo, hi = c, c
	}
	flush()
	return hunks
}

func writeHunk(sb *strings.Builder, lines []unifiedLine, h hunk) {
	oldStart, oldCount := rangeStart(lines, h, true)
	newStart, newCount := rangeStart(lines, h, false)

	fmt.Fprintf(sb, "@@ -%s +%s @@\n", formatRange(oldStart, oldCount), formatRange(newStart, newCount))
	for i := h.start; i <= h.end; i++ {
		line := lines[i]
		sb.WriteByte(line.tag)
		sb.WriteString(line.text)
		if !strings.HasSuffix(line.text, "\n") {
			sb.WriteByte('\n')
			sb.WriteString("\\ No newline at end of file\n")
		}
	}
}

// rangeStart returns the first line number and total line count for the old
// (oldSide true) or new (oldSide false) side of a hunk.
func rangeStart(lines []unifiedLine, h hunk, oldSide bool) (start, count int) {
	has := func(l unifiedLine) bool {
		if oldSide {
			return l.hasOld
		}
		return l.hasNew
	}
	num := func(l unifiedLine) int {
		if oldSide {
			return l.oldNo
		}
		return l.newNo
	}

	for i := h.start; i <= h.end; i++ {
		if has(lines[i]) {
			count++
		}
	}
	if count > 0 {
		for i := h.start; i <= h.end; i++ {
			if has(lines[i]) {
				return num(lines[i]), count
			}
		}
	}
	// No lines on this side: the range is empty and starts just before the
	// first line of the hunk.
	return num(lines[h.start]) - 1, 0
}

func formatRange(start, count int) string {
	if count == 1 {
		return fmt.Sprintf("%d", start)
	}
	return fmt.Sprintf("%d,%d", start, count)
}

// computeOps runs Myers' O(ND) diff algorithm over the two line slices and
// returns the edit script that turns a into b.
func computeOps(a, b []string) []Op {
	n, m := len(a), len(b)
	maxD := n + m
	offset := maxD
	v := make([]int, 2*maxD+1)
	trace := make([][]int, 0, maxD+1)

	for d := 0; d <= maxD; d++ {
		snapshot := make([]int, len(v))
		copy(snapshot, v)
		trace = append(trace, snapshot)

		for k := -d; k <= d; k += 2 {
			var x int
			if k == -d || (k != d && v[offset+k-1] < v[offset+k+1]) {
				x = v[offset+k+1]
			} else {
				x = v[offset+k-1] + 1
			}
			y := x - k
			for x < n && y < m && a[x] == b[y] {
				x++
				y++
			}
			v[offset+k] = x
			if x >= n && y >= m {
				return backtrack(trace, a, b, offset)
			}
		}
	}
	return nil
}

func backtrack(trace [][]int, a, b []string, offset int) []Op {
	x, y := len(a), len(b)
	ops := make([]Op, 0, x+y)

	for d := len(trace) - 1; d >= 0; d-- {
		v := trace[d]
		k := x - y

		var prevK int
		if k == -d || (k != d && v[offset+k-1] < v[offset+k+1]) {
			prevK = k + 1
		} else {
			prevK = k - 1
		}
		prevX := v[offset+prevK]
		prevY := prevX - prevK

		for x > prevX && y > prevY {
			ops = append(ops, Op{Kind: Equal, Text: a[x-1]})
			x--
			y--
		}
		if d > 0 {
			if x == prevX {
				ops = append(ops, Op{Kind: Insert, Text: b[prevY]})
			} else {
				ops = append(ops, Op{Kind: Delete, Text: a[prevX]})
			}
		}
		x, y = prevX, prevY
	}

	for i, j := 0, len(ops)-1; i < j; i, j = i+1, j-1 {
		ops[i], ops[j] = ops[j], ops[i]
	}
	return ops
}

// splitLines splits s into lines, keeping each line's trailing newline. A
// non-empty final line without a newline is returned as-is.
func splitLines(s string) []string {
	if s == "" {
		return nil
	}
	lines := strings.SplitAfter(s, "\n")
	if lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	return lines
}

package diff

import (
	"strings"
	"testing"
)

func TestUnifiedIdentical(t *testing.T) {
	if got := Unified("a\nb\nc\n", "a\nb\nc\n"); got != "" {
		t.Fatalf("expected empty diff, got:\n%s", got)
	}
}

func TestUnifiedReplaceLine(t *testing.T) {
	got := UnifiedNamed("old.txt", "new.txt", "hello\n", "world\n")
	want := strings.Join([]string{
		"--- old.txt",
		"+++ new.txt",
		"@@ -1 +1 @@",
		"-hello",
		"+world",
		"",
	}, "\n")
	if got != want {
		t.Fatalf("got:\n%q\nwant:\n%q", got, want)
	}
}

func TestUnifiedInsertIntoEmpty(t *testing.T) {
	got := Unified("", "x\ny\n")
	want := strings.Join([]string{
		"--- a",
		"+++ b",
		"@@ -0,0 +1,2 @@",
		"+x",
		"+y",
		"",
	}, "\n")
	if got != want {
		t.Fatalf("got:\n%q\nwant:\n%q", got, want)
	}
}

func TestUnifiedDeleteToEmpty(t *testing.T) {
	got := Unified("x\ny\n", "")
	want := strings.Join([]string{
		"--- a",
		"+++ b",
		"@@ -1,2 +0,0 @@",
		"-x",
		"-y",
		"",
	}, "\n")
	if got != want {
		t.Fatalf("got:\n%q\nwant:\n%q", got, want)
	}
}

func TestUnifiedAppendToFile(t *testing.T) {
	a := "l1\nl2\nl3\nl4\nl5\n"
	b := "l1\nl2\nl3\nl4\nl5\nl6\n"
	got := Unified(a, b)
	want := strings.Join([]string{
		"--- a",
		"+++ b",
		"@@ -3,3 +3,4 @@",
		" l3",
		" l4",
		" l5",
		"+l6",
		"",
	}, "\n")
	if got != want {
		t.Fatalf("got:\n%s\nwant:\n%s", got, want)
	}
}

func TestUnifiedMultipleHunks(t *testing.T) {
	var a, b []string
	for i := 1; i <= 20; i++ {
		a = append(a, "line"+itoa(i))
	}
	b = append(b, a...)
	b[1] = "changed2"
	b[17] = "changed18"

	got := Unified(strings.Join(a, "\n")+"\n", strings.Join(b, "\n")+"\n")
	want := strings.Join([]string{
		"--- a",
		"+++ b",
		"@@ -1,6 +1,6 @@",
		" line1",
		"-line2",
		"+changed2",
		" line3",
		" line4",
		" line5",
		" line6",
		"@@ -15,6 +15,6 @@",
		" line15",
		" line16",
		" line17",
		"-line18",
		"+changed18",
		" line19",
		" line20",
		"",
	}, "\n")
	if got != want {
		t.Fatalf("got:\n%s\nwant:\n%s", got, want)
	}
}

func TestUnifiedNoTrailingNewline(t *testing.T) {
	got := Unified("a\nb", "a\nc")
	want := strings.Join([]string{
		"--- a",
		"+++ b",
		"@@ -1,2 +1,2 @@",
		" a",
		"-b",
		"\\ No newline at end of file",
		"+c",
		"\\ No newline at end of file",
		"",
	}, "\n")
	if got != want {
		t.Fatalf("got:\n%q\nwant:\n%q", got, want)
	}
}

func TestUnifiedContextZero(t *testing.T) {
	got := Config{Context: -1}.Unified("a\nb\n", "a\nc\n")
	want := strings.Join([]string{
		"--- a",
		"+++ b",
		"@@ -2 +2 @@",
		"-b",
		"+c",
		"",
	}, "\n")
	if got != want {
		t.Fatalf("got:\n%s\nwant:\n%s", got, want)
	}
}

// TestComputeOpsRoundTrip verifies the edit script reconstructs the new text
// from the old text for a range of inputs.
func TestComputeOpsRoundTrip(t *testing.T) {
	cases := [][2][]string{
		{nil, nil},
		{{"a"}, nil},
		{nil, {"a"}},
		{{"a", "b", "c"}, {"a", "c"}},
		{{"a", "c"}, {"a", "b", "c"}},
		{{"a", "b"}, {"c", "d"}},
		{{"a", "b", "c", "d"}, {"a", "x", "c", "y"}},
	}
	for _, tc := range cases {
		ops := computeOps(tc[0], tc[1])
		var rebuilt, old []string
		for _, op := range ops {
			switch op.Kind {
			case Equal:
				rebuilt = append(rebuilt, op.Text)
				old = append(old, op.Text)
			case Delete:
				old = append(old, op.Text)
			case Insert:
				rebuilt = append(rebuilt, op.Text)
			}
		}
		if !equalSlices(rebuilt, tc[1]) {
			t.Errorf("rebuilt %q, want %q", rebuilt, tc[1])
		}
		if !equalSlices(old, tc[0]) {
			t.Errorf("consumed old %q, want %q", old, tc[0])
		}
	}
}

func equalSlices(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	return string(buf[i:])
}

// Command difftool prints a unified diff between two text files.
//
// Usage:
//
//	difftool [flags] <old-file> <new-file>
//
// A file name of "-" reads from standard input (at most one side may be
// stdin). The exit status is 0 when the inputs are identical, 1 when they
// differ, and 2 on error.
package main

import (
	"flag"
	"fmt"
	"io"
	"os"

	"difftool/diff"
)

func main() {
	context := flag.Int("context", 3, "number of context lines to show around changes")
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), "usage: %s [flags] <old-file> <new-file>\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()

	if flag.NArg() != 2 {
		flag.Usage()
		os.Exit(2)
	}

	oldName, newName := flag.Arg(0), flag.Arg(1)
	oldText, err := readInput(oldName)
	if err != nil {
		fmt.Fprintf(os.Stderr, "difftool: %v\n", err)
		os.Exit(2)
	}
	newText, err := readInput(newName)
	if err != nil {
		fmt.Fprintf(os.Stderr, "difftool: %v\n", err)
		os.Exit(2)
	}

	cfg := diff.Config{
		FromName: label(oldName),
		ToName:   label(newName),
		Context:  *context,
	}
	out := cfg.Unified(string(oldText), string(newText))
	if out == "" {
		return
	}
	fmt.Print(out)
	os.Exit(1)
}

func readInput(name string) ([]byte, error) {
	if name == "-" {
		return io.ReadAll(os.Stdin)
	}
	return os.ReadFile(name)
}

// label replaces the stdin marker with a readable name in diff headers.
func label(name string) string {
	if name == "-" {
		return "stdin"
	}
	return name
}

